<script setup lang="ts">
import type { AdvancedFilter } from './services/voucherSearch'
const props=defineProps<{open:boolean;value:AdvancedFilter}>()
const emit=defineEmits<{close:[];apply:[value:AdvancedFilter]}>()
const draft=reactive<AdvancedFilter>({})
watch(()=>props.open,open=>{if(open){for(const key of Object.keys(draft))delete draft[key as keyof AdvancedFilter];Object.assign(draft,props.value)}})
const error=ref('')
function apply(){for(const [min,max] of [[draft.supplyMin,draft.supplyMax],[draft.vatMin,draft.vatMax]]){if((min&&!/^\d{1,15}$/.test(min))||(max&&!/^\d{1,15}$/.test(max))||(min&&max&&BigInt(min)>BigInt(max))){error.value='금액 범위는 작은 금액부터 원 단위 정수로 입력하세요.';return}}error.value='';emit('apply',{...draft});emit('close')}
</script>
<template><UiModal :open="open" title="전표 상세 검색" @close="emit('close')"><div class="search-fields"><label>번호<input v-model="draft.number" /></label><label>거래처·사업자번호<input v-model="draft.partner" /></label><label>품목<input v-model="draft.item" /></label><label>적요·메모<input v-model="draft.memo" /></label><label>매출·매입<select v-model="draft.direction"><option value="">전체</option><option value="sales">매출</option><option value="purchase">매입</option></select></label><label>유형코드<input v-model="draft.type" /></label><label>분개유형<select v-model="draft.journalType"><option value="">전체</option><option v-for="code in ['0','1','2','3','4','5']" :key="code">{{ code }}</option></select></label><label>전자증빙<select v-model="draft.electronic"><option value="">전체</option><option value="yes">전자</option><option value="no">종이</option></select></label><label>공급가액 최소<input v-model="draft.supplyMin" /></label><label>공급가액 최대<input v-model="draft.supplyMax" /></label><label>부가세 최소<input v-model="draft.vatMin" /></label><label>부가세 최대<input v-model="draft.vatMax" /></label><label><input v-model="draft.unbalanced" type="checkbox" />대차 불일치</label><label><input v-model="draft.duplicatesOnly" type="checkbox" />중복 의심</label></div><p v-if="error" role="alert">{{ error }}</p><template #footer><UiButton @click="emit('apply',{});emit('close')">조건 초기화</UiButton><UiButton @click="apply">검색 적용</UiButton></template></UiModal></template>
<style scoped>.search-fields{display:grid;grid-template-columns:1fr 1fr;gap:12px}.search-fields label{display:grid;gap:5px}.search-fields input,.search-fields select{padding:7px;border:1px solid #cbd5e1;border-radius:4px}</style>
